<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
const user=ref<any>(null),csrf=ref(''),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(true);
const username=ref('admin'),password=ref('DemoAdmin-2026!');
const data=ref<any>({clubs:[],devices:[],games:[],jobs:[]});
const clubId=ref('aurora'),search=ref(''),tab=ref('devices'),selected=ref<string[]>([]),gameId=ref('fortnite'),variant=ref<number>(36);
const confirm=ref<string|null>(null),feedback=ref<Record<string,any>>({});
const histPc=ref(''),histGame=ref(''),histFrom=ref(''),histTo=ref(''),history=ref<any[]>([]);
const club=computed(()=>data.value.clubs.find((c:any)=>c.id===clubId.value));
const game=computed(()=>data.value.games.find((g:any)=>g.id===gameId.value));
const devices=computed(()=>data.value.devices.filter((d:any)=>d.clubId===clubId.value));
const clubs=computed(()=>data.value.clubs.filter((c:any)=>c.name.toLowerCase().includes(search.value.toLowerCase())));
const jobs=computed(()=>data.value.jobs.filter((j:any)=>j.clubId===clubId.value).slice(0,60));
const variants=computed(()=>club.value?.variants??[]);
const chosen=computed(()=>devices.value.filter((d:any)=>selected.value.includes(d.id)));
const canApply=computed(()=>!!game.value?.exes.length&&variants.value.some((v:any)=>v.id===variant.value)&&selected.value.length>0);
const statusNames:Record<string,string>={queued:'В очереди',running:'Выполняется',succeeded:'Выполнено',failed:'Ошибка',expired:'Истекло',unknown:'Неизвестно'};
const operations:Record<string,string>={apply_marking:'Применить',remove_marking:'Удалить',inspect_rules:'Инспекция',health:'Проверка агента'};
const scenarioNames:Record<string,string>={success:'Успех',offline:'Офлайн',rights:'Нет прав',partial:'Частичный сбой + откат',lost:'Потеря ответа',conflict:'Чужие правила'};
const reasons:Record<string,string>={launch:'Запуск / авторизация',server:'Подключение к серверу',ping:'Пинг',voice:'Голосовой чат',other:'Другое'};
const fmt=(n:number|null)=>n?new Date(n).toLocaleString('ru-RU'):'Нет данных';
async function api(path:string,method='GET',body?:unknown){const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.value},body:body===undefined?undefined:JSON.stringify(body)});const b=await r.json();if(!r.ok){if(r.status===401&&path!=='/login')user.value=null;throw Error(b.message??'Ошибка запроса');}return b;}
async function act(fn:()=>Promise<void>){error.value='';notice.value='';busy.value=true;try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function login(){await act(async()=>{const r=await api('/login','POST',{username:username.value,password:password.value});user.value=r.user;csrf.value=r.csrf;password.value='';await refresh();});}
async function loadHistory(){const q=new URLSearchParams({clubId:clubId.value});if(histPc.value)q.set('deviceId',histPc.value);if(histGame.value)q.set('gameId',histGame.value);if(histFrom.value)q.set('from',String(new Date(histFrom.value).getTime()));if(histTo.value)q.set('to',String(new Date(histTo.value).getTime()));history.value=await api('/history?'+q);}
async function refresh(){if(!user.value)return;data.value=await api('/state');if(tab.value==='history')await loadHistory();}
function recommendation(d:any){const j=data.value.jobs.filter((j:any)=>j.deviceId===d.id&&j.gameId===gameId.value&&j.operation==='apply_marking'&&j.state==='succeeded'&&j.feedback?.outcome==='helped').sort((a:any,b:any)=>b.feedback.at-a.feedback.at)[0];return j?`${j.variantName??j.variant} · ${fmt(j.feedback.at)} · ${reasons[j.feedback.reason]}${variants.value.some((v:any)=>v.id===j.variant)?'':' · сейчас недоступен'}`:'Нет отметки «помогло»';}
function lastJob(d:any){return data.value.jobs.find((j:any)=>j.deviceId===d.id);}
function requestOperation(op:string){if(selected.value.length>1&&['apply_marking','remove_marking'].includes(op))confirm.value=op;else void run(op);}
async function run(op:string){confirm.value=null;await act(async()=>{await api('/jobs','POST',{deviceIds:selected.value,gameId:gameId.value,variant:op==='apply_marking'?variant.value:undefined,operation:op});notice.value='Задание создано. Результаты появятся отдельно для каждого ПК.';await refresh();});}
async function reboot(d:any){await act(async()=>{await api(`/demo/devices/${d.id}/reboot`,'POST',{});notice.value='DEMO: новая загрузочная сессия. Временные правила исчезли; история сохранена. Автовосстановления нет.';await refresh();});}
async function scenario(d:any,event:Event){await act(async()=>{await api(`/demo/devices/${d.id}/scenario`,'POST',{scenario:(event.target as HTMLSelectElement).value});await refresh();});}
async function reconcile(j:any){await act(async()=>{await api(`/demo/jobs/${j.id}/reconcile`,'POST',{});await refresh();});}
function draft(j:any){return feedback.value[j.id]??(feedback.value[j.id]={outcome:j.feedback?.outcome??'unchecked',reason:j.feedback?.reason??'launch',comment:j.feedback?.comment??''});}
async function saveFeedback(j:any){await act(async()=>{await api(`/jobs/${j.id}/feedback`,'POST',draft(j));notice.value='Отметка сохранена для всех сотрудников.';await refresh();});}
const editId=ref(''),editName=ref(''),editExes=ref('');
function edit(g:any){editId.value=g.id;editName.value=g.name;editExes.value=g.exes.join('\n');}
async function saveGame(){await act(async()=>{await api('/admin/games'+(editId.value?'/'+editId.value:''),editId.value?'PUT':'POST',{name:editName.value,exes:editExes.value.split(/\n/).map(s=>s.trim()).filter(Boolean)});editId.value='';editName.value='';editExes.value='';await refresh();notice.value='Каталог сохранён. Старые задания сохранили свою ревизию.';});}
const clubEditId=ref(''),clubName=ref(''),clubVariants=ref('36:Вариант 36\n40:Вариант 40');
function editClub(c:any){clubEditId.value=c.id;clubName.value=c.name;clubVariants.value=c.variants.map((v:any)=>`${v.id}:${v.name}`).join('\n');}
async function saveClub(){await act(async()=>{const vv=clubVariants.value.split('\n').filter(s=>s.trim()).map(s=>{const i=s.indexOf(':');return {id:Number(s.slice(0,i)),name:s.slice(i+1)};});await api('/admin/clubs'+(clubEditId.value?'/'+clubEditId.value:''),clubEditId.value?'PUT':'POST',{name:clubName.value,variants:vv});await refresh();notice.value='Клуб сохранён.';});}
const users=ref<any[]>([]),newUser=ref(''),newPassword=ref(''),newRole=ref('operator');
async function loadUsers(){users.value=await api('/admin/users');}
async function addUser(){await act(async()=>{await api('/admin/users','POST',{username:newUser.value,password:newPassword.value,role:newRole.value});newPassword.value='';await loadUsers();notice.value='Пользователь создан.';});}
async function updateUser(u:any){await act(async()=>{await api('/admin/users/'+u.id,'PUT',{role:u.role,disabled:u.disabled});await loadUsers();});}
async function revoke(d:any){await act(async()=>{await api('/admin/devices/'+d.id+'/revoke','POST',{});await refresh();});}
const enrollment=ref('');async function issueEnrollment(){await act(async()=>{const e=await api('/admin/enrollments','POST',{clubId:clubId.value});enrollment.value=e.token;notice.value='Одноразовый токен действует 10 минут. Передайте его через защищённый локальный файл; не публикуйте.';});}
watch(clubId,()=>{selected.value=[];histPc.value='';variant.value=variants.value[0]?.id;enrollment.value='';});
watch([tab,histPc,histGame,histFrom,histTo,clubId],()=>{if(user.value&&tab.value==='history')void act(loadHistory);if(user.value?.role==='admin'&&tab.value==='admin')void act(loadUsers);});
let timer:ReturnType<typeof setInterval>;
onMounted(async()=>{try{const h=await api('/health');data.value.mode=h.mode;if(h.mode==='PILOT'){username.value='';password.value='';}const r=await api('/me');user.value=r.user;csrf.value=r.csrf;await refresh();}catch{}loading.value=false;timer=setInterval(()=>{if(user.value&&!busy.value)void refresh().catch(e=>error.value=e.message);},1500);});
onUnmounted(()=>clearInterval(timer));
</script>

<template>
<div v-if="loading" class="loading">Загрузка панели…</div>
<div v-else-if="!user" class="login-wrap">
 <form class="login-card" @submit.prevent="login"><div class="brand-mark">P<span>·</span>T</div><p class="eyebrow">PANELTECH / SUPPORT TOOLS</p><h1>Маркировка игр</h1><p class="muted">Рабочее место поддержки компьютерных клубов</p><div class="demo-note"><b>{{data.mode==='PILOT'?'ОТДЕЛЬНЫЙ ПИЛОТНЫЙ СТЕНД':'ДОМАШНЯЯ ДЕМОНСТРАЦИЯ'}}</b><br>{{data.mode==='PILOT'?'Реальные операции разрешаются только локальной настройкой агента.':'Вымышленные ПК. Изменения QoS не выполняются.'}}</div><label>Логин<input v-model="username" autocomplete="username" required></label><label>Пароль<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary full" :disabled="busy">Войти в панель →</button><details v-if="data.mode!=='PILOT'"><summary>Демонстрационные учётные записи</summary><p>admin / DemoAdmin-2026!<br>operator / DemoOperator-2026!</p></details></form>
</div>
<div v-else class="shell">
 <aside class="sidebar"><div class="brand"><div class="brand-mark small">P<span>·</span>T</div><div>PanelTech<small>Панель поддержки</small></div></div><span class="demo-pill">● {{data.mode==='PILOT'?'PILOT / WINDOWS':'DEMO / СИМУЛЯЦИЯ'}}</span><p class="side-label">КЛУБЫ <span>{{data.clubs.length}}</span></p><input v-model="search" placeholder="Поиск клуба" aria-label="Поиск клуба"><nav class="clubs"><button v-for="c in clubs" :key="c.id" :class="{active:clubId===c.id}" @click="clubId=c.id"><span class="club-icon">▦</span>{{c.name}}<small>{{data.devices.filter((d:any)=>d.clubId===c.id&&d.online).length}} в сети</small></button><p v-if="!clubs.length" class="muted">Клубы не найдены</p></nav><div class="sidebar-bottom"><b>{{user.username}}</b><span>{{user.role==='admin'?'Администратор':'Оператор'}}</span><button @click="act(async()=>{await api('/logout','POST',{});user=null;})">Выйти</button></div></aside>
 <main>
  <header><div><p class="eyebrow">КЛУБ / {{club?.demo?'ДЕМОНСТРАЦИЯ':'ПИЛОТ'}}</p><h1>{{club?.name??'Выберите клуб'}}</h1></div><div class="header-meta"><span class="live-dot"></span> API подключён<small>{{devices.filter((d:any)=>d.online).length}} из {{devices.length}} ПК доступны</small></div></header>
  <div class="demo-banner"><b>{{data.mode??'DEMO'}}</b><span>{{data.mode==='PILOT'?'Проверка QoS-правил не подтверждает маршрут MikroTik, пинг или голосовой чат.':'Результаты симуляции не подтверждают маркировку Windows, маршрут MikroTik, пинг или голосовой чат.'}}</span></div>
  <div class="tabs"><button v-for="t in [['devices','Компьютеры'],['history','История'],...(user.role==='admin'?[['catalog','Каталог игр'],['admin','Управление']]:[])]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></div>
  <div v-if="error" class="error toast" role="alert">{{error}}<button @click="error=''">×</button></div><div v-if="notice" class="notice toast" role="status">{{notice}}<button @click="notice=''">×</button></div>
  <template v-if="tab==='devices'">
   <section class="action-panel"><div><p class="eyebrow">НОВАЯ ОПЕРАЦИЯ</p><h2>Управление маркировкой</h2></div><div class="action-fields"><label>Игра<select v-model="gameId"><option v-for="g in data.games" :value="g.id" :key="g.id">{{g.name}}</option></select></label><label>Вариант клуба<select v-model="variant"><option v-for="v in variants" :value="v.id" :key="v.id">{{v.name}} · {{v.id}}</option></select></label><button class="primary" :disabled="busy||!canApply" @click="requestOperation('apply_marking')">Применить к {{selected.length}} ПК →</button></div><div class="action-footer"><span>Выбрано <b>{{selected.length}}</b> ПК · {{game?.exes.length??0}} exe · ревизия {{game?.revision}}</span><div><button :disabled="busy||!selected.length||!game?.exes.length" @click="requestOperation('remove_marking')">Удалить правила игры</button><button :disabled="busy||!selected.length" @click="requestOperation('inspect_rules')">Инспекция</button><button :disabled="busy||!selected.length" @click="requestOperation('health')">Проверка агента</button></div></div><p v-if="!game?.exes.length" class="error">Для игры не заполнен список exe. Применение и удаление заблокированы.</p><p class="fine">36 / 39 / 40 / 41 — локальные варианты клуба. Маршрутизация автоматически не подтверждается. При выборе группы рекомендации показаны отдельно для каждого ПК.</p></section>
   <section class="panel"><div class="section-heading"><h2>Компьютеры <span class="count">{{devices.length}}</span></h2><button @click="selected=selected.length===devices.length?[]:devices.map((d:any)=>d.id)">{{selected.length===devices.length?'Снять выбор':'Выбрать все'}}</button></div><div class="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="Выбрать все ПК" :checked="!!devices.length&&selected.length===devices.length" @change="selected=selected.length===devices.length?[]:devices.map((d:any)=>d.id)"></th><th>Компьютер</th><th>Доступность</th><th>Последняя операция</th><th>Помогло для этой игры</th><th>Сценарий DEMO</th></tr></thead><tbody><tr v-for="d in devices" :key="d.id" :class="{selected:selected.includes(d.id)}"><td><input type="checkbox" :value="d.id" v-model="selected" :aria-label="'Выбрать '+d.name"></td><td><b>{{d.name}}</b><small class="mono">{{d.id}}</small><button v-if="d.demo" class="text-button" :disabled="busy" @click="reboot(d)">Имитировать перезагрузку</button></td><td><span class="availability" :class="{online:d.online}">{{d.online?'● В сети':'○ Недоступен'}}</span><small>{{fmt(d.lastSeen)}}</small><small>Инспекция: {{d.fresh?'актуальна':'устарела / отсутствует'}}</small></td><td><span v-if="lastJob(d)" class="badge" :class="lastJob(d).state">{{statusNames[lastJob(d).state]}}</span><span v-else class="muted">Нет операций</span><small v-if="lastJob(d)">{{lastJob(d).message??'Ожидает агента'}}</small></td><td class="recommendation">{{recommendation(d)}}</td><td><select v-if="d.demo" :value="d.scenario" :aria-label="'Сценарий '+d.name" @change="scenario(d,$event)"><option v-for="(name,id) in scenarioNames" :key="id" :value="id">{{name}}</option></select><span v-else>Windows</span><small>{{d.fresh?'Правил':'Кэш правил'}}: {{d.rules.length}}</small><details><summary>{{d.fresh?'Состояние правил':'Последний снимок (не текущее состояние)'}}</summary><pre>{{JSON.stringify(d.rules,null,2)}}</pre><small>Инспекция {{fmt(d.inspectedAt)}} · boot {{d.bootId}}</small></details></td></tr><tr v-if="!devices.length"><td colspan="6" class="empty">В клубе нет зарегистрированных ПК.</td></tr></tbody></table></div></section>
   <section class="panel results"><div class="section-heading"><h2>Результаты по ПК</h2><span class="muted">Последние 60 операций клуба</span></div><p v-if="!jobs.length" class="empty">Выберите ПК и примените вариант. Здесь появятся индивидуальные результаты.</p><article v-for="j in jobs" :key="j.id" class="job"><div class="job-top"><b>{{j.deviceName}} <span class="subtle">/ {{j.gameName}}</span></b><span><span class="demo-tag">{{j.demo?'DEMO':'WINDOWS'}}</span> <span class="badge" :class="j.state">{{statusNames[j.state]}}</span></span></div><p>{{j.message??'Ожидание выполнения агентом…'}}</p><small>{{operations[j.operation]}} · {{j.variantName??'без варианта'}} · {{fmt(j.created)}} · {{j.author}} · exe r{{j.revision}}</small><p v-if="j.rollback" class="rollback">Откат: {{j.rollback}}</p><button v-if="j.state==='unknown'&&j.demo" :disabled="busy" @click="reconcile(j)">Сверить фактические правила симулятора</button><div v-if="j.state==='succeeded'&&j.operation==='apply_marking'" class="feedback"><label>Результат со слов сотрудника<select v-model="draft(j).outcome"><option value="unchecked">Не проверено</option><option value="helped">Помогло</option><option value="not_helped">Не помогло</option></select></label><label>Симптом<select v-model="draft(j).reason"><option v-for="(v,k) in reasons" :value="k" :key="k">{{v}}</option></select></label><label>Комментарий<input v-model="draft(j).comment" maxlength="1000" placeholder="Необязательно"></label><button :disabled="busy" @click="saveFeedback(j)">Сохранить отметку</button></div><small v-if="j.feedback">Отметка: {{j.feedback.outcome==='helped'?'помогло':j.feedback.outcome==='not_helped'?'не помогло':'не проверено'}} · {{j.feedback.author}} · {{fmt(j.feedback.at)}}</small><details><summary>Технические данные</summary><pre>{{JSON.stringify(j,null,2)}}</pre></details></article></section>
  </template>
  <section v-if="tab==='history'" class="panel"><div class="section-heading"><h2>История операций</h2><span class="muted">Сохраняется после перезапуска API</span></div><div class="filters"><label>ПК<select v-model="histPc"><option value="">Все ПК клуба</option><option v-for="d in devices" :value="d.id" :key="d.id">{{d.name}}</option></select></label><label>Игра<select v-model="histGame"><option value="">Все игры</option><option v-for="g in data.games" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>С<input type="datetime-local" v-model="histFrom"></label><label>По<input type="datetime-local" v-model="histTo"></label></div><div class="table-scroll"><table><thead><tr><th>Дата / автор</th><th>ПК / игра</th><th>Операция</th><th>Технический результат</th><th>Отметка сотрудника</th></tr></thead><tbody><tr v-for="j in history" :key="j.id"><td>{{fmt(j.created)}}<small>{{j.author}} · {{j.demo?'DEMO':'Windows'}}</small></td><td><b>{{j.deviceName}}</b><small>{{j.gameName}} · r{{j.revision}}</small></td><td>{{operations[j.operation]}}<small>{{j.variantName??'—'}}</small></td><td><span class="badge" :class="j.state">{{statusNames[j.state]}}</span><small>{{j.message}}</small><small v-if="j.rollback">Откат: {{j.rollback}}</small></td><td>{{j.feedback?({helped:'Помогло',not_helped:'Не помогло',unchecked:'Не проверено'} as any)[j.feedback.outcome]:'Не проверено'}}<small v-if="j.feedback">{{reasons[j.feedback.reason]}} · {{j.feedback.author}}<br>{{j.feedback.comment}}</small><details><summary>Снимок задания</summary><pre>{{JSON.stringify(j,null,2)}}</pre></details></td></tr><tr v-if="!history.length"><td colspan="5" class="empty">По этим фильтрам операций нет.</td></tr></tbody></table></div></section>
  <div v-if="tab==='catalog'&&user.role==='admin'" class="two-columns"><section class="panel padded"><h2>Каталог игр</h2><p class="muted">Fortnite — стартовый набор пользователя, без аудита актуальных файлов. PUBG — пустая карточка.</p><article v-for="g in data.games" :key="g.id" class="catalog-item"><b>{{g.name}}</b><small>Ревизия {{g.revision}} · {{g.exes.length}} exe</small><code v-for="e in g.exes" :key="e">{{e}}</code><button @click="edit(g)">Редактировать</button></article></section><form class="panel padded" @submit.prevent="saveGame"><h2>{{editId?'Изменить игру':'Новая игра'}}</h2><label>Название<input v-model="editName" maxlength="100" required></label><label>Имена exe, по одному в строке<textarea v-model="editExes" rows="9" placeholder="EpicGamesLauncher.exe"></textarea></label><p class="fine">Только имена файлов .exe. Пути, команды, аргументы и PowerShell запрещены. Изменение создаёт новую ревизию.</p><button class="primary" :disabled="busy">Сохранить игру</button><button type="button" @click="editId='';editName='';editExes=''">Новая карточка</button></form></div>
  <div v-if="tab==='admin'&&user.role==='admin'" class="two-columns"><section class="panel padded"><h2>Клубы и варианты</h2><article v-for="c in data.clubs" :key="c.id" class="catalog-item"><b>{{c.name}}</b><small>{{c.variants.map((v:any)=>v.id+' '+v.name).join(' / ')}}</small><button @click="editClub(c)">Редактировать</button></article><form @submit.prevent="saveClub"><h3>{{clubEditId?'Изменить клуб':'Новый клуб'}}</h3><label>Название<input v-model="clubName" required></label><label>Варианты, ID:название<textarea v-model="clubVariants" rows="4" required></textarea></label><button :disabled="busy" class="primary">Сохранить клуб</button><button type="button" @click="clubEditId='';clubName=''">Новый</button></form><hr><h3>Регистрация агента</h3><p class="fine">{{data.realAgents?'Разрешена явно на сервере. Выберите отдельный реальный клуб.':'Реальные агенты отключены. DEMO не подключает настоящие ПК.'}}</p><button :disabled="busy||!data.realAgents||club?.demo" @click="issueEnrollment">Выдать токен для {{club?.name}}</button><code v-if="enrollment" class="secret">{{enrollment}}</code><h3>Отзыв устройства</h3><div v-for="d in devices" :key="d.id" class="user-row"><b>{{d.name}}</b><span>{{d.revoked?'Отозван':'Активен'}}</span><button :disabled="busy||d.revoked" @click="revoke(d)">Отозвать</button></div></section><section class="panel padded"><h2>Сотрудники</h2><div v-for="u in users" :key="u.id" class="user-row"><b>{{u.username}}</b><select v-model="u.role" :disabled="u.id===user.id"><option value="admin">Администратор</option><option value="operator">Оператор</option></select><label class="inline"><input type="checkbox" v-model="u.disabled" :disabled="u.id===user.id">Отключён</label><button :disabled="busy||u.id===user.id" @click="updateUser(u)">Сохранить</button></div><form @submit.prevent="addUser"><h3>Добавить сотрудника</h3><label>Логин<input v-model="newUser" required pattern="[a-zA-Z0-9_.-]{3,50}"></label><label>Пароль, минимум 12 символов<input v-model="newPassword" type="password" minlength="12" autocomplete="new-password" required></label><label>Роль<select v-model="newRole"><option value="operator">Оператор</option><option value="admin">Администратор</option></select></label><button class="primary" :disabled="busy">Создать пользователя</button></form></section></div>
  <footer>PanelTech MVP · Состояние правил и пользовательская отметка — разные результаты. История не запускает восстановление правил.</footer>
 </main>
 <div v-if="confirm" class="modal-backdrop" @click.self="confirm=null"><section role="dialog" aria-modal="true" aria-labelledby="confirm-title" class="modal"><p class="eyebrow">МАССОВОЕ ЗАДАНИЕ · {{data.mode}}</p><h2 id="confirm-title">{{operations[confirm]}} маркировку?</h2><dl><dt>Клуб</dt><dd>{{club?.name}}</dd><dt>Компьютеры</dt><dd>{{chosen.length}}: {{chosen.map((d:any)=>d.name).join(', ')}}</dd><dt>Игра</dt><dd>{{game?.name}} · {{game?.exes.length}} exe</dd><dt>Вариант</dt><dd>{{confirm==='apply_marking'?variants.find((v:any)=>v.id===variant)?.name:'Удаление собственных правил игры'}}</dd></dl><p class="muted">Недоступные ПК будут пропущены. Ошибка одного ПК не остановит остальные.</p><div class="modal-actions"><button @click="confirm=null">Отмена</button><button class="primary" :disabled="busy" @click="run(confirm!)">Запустить для {{chosen.length}} ПК</button></div></section></div>
</div>
</template>
